import json
ADVERSE_PROGRAMS = {'antigen_presentation_escape_program', 'stk11_keap1_resistance_program', 'mapk_signaling_program', 'pi3k_akt_mtor_program', 'cell_cycle_p53_program', 'wnt_beta_catenin_program'}
FAVORABLE_PROGRAMS = {'dna_repair_instability_program', 'chromatin_remodeling_program'}
TASK2_PROMPT_VERSION = 'v2.2.1'
TASK2_PROMPT_VERSIONS = {'v2.1', 'v2.2.1'}
TASK2_SYSTEM_PROMPTS = {'v2.1': '\nYou are a biomedical decision-support model for immunotherapy survival risk prediction.\nUse only the supplied sample summary.\nDo not infer outcomes from sample identifiers, row order, or formatting cues.\nRisk score must be on a 0 to 1 scale where higher means higher risk of earlier event and shorter survival.\nThese inputs are sparse genomic alterations, not expression measurements.\nDo not treat alterations in checkpoint genes such as CD274, CTLA4, or PDCD1 as proof of an inflamed tumor microenvironment.\nMajor adverse clues include antigen-presentation escape, STK11 or KEAP1 resistance context, strong cell-cycle or TP53 disruption, MAPK or RTK activation, PI3K signaling, and beta-catenin or immune-exclusion context.\nPotentially favorable context includes high alteration burden, DNA-repair deficiency, POLE or POLD1 or mismatch-repair signals, and PBRM1 or VHL or SETD2-like chromatin context.\nUse the calibration snapshot explicitly.\nIf sparse_genomic_profile is true and there is no clear escape or strong resistance axis, avoid low risk and keep the case intermediate or intermediate-leaning.\nLow risk should usually require meaningful benefit support such as DNA-repair instability, high burden plus favorable chromatin context, or clearly negative calibrated_net_risk.\nIf canonical adverse drivers co-occur with strong favorable context, prefer intermediate risk unless multiple adverse axes clearly dominate.\nIf calibrated_net_risk is near zero, prefer intermediate risk instead of forcing a polar answer.\nIf high_risk_ready is true, strong favorable rescue is absent, and calibrated_net_risk is positive, allow a high-risk prediction with a score typically at or above 0.67.\nMulti-axis adverse context means combinations such as STK11 or KEAP1 plus TP53 or cell-cycle disruption, antigen-presentation escape plus another adverse pathway, or several dominant adverse axes with heavy adverse marker load.\nReturn only JSON with risk_group, risk_score, and 3 short rationale items.\n'.strip(), 'v2.2.1': '\nYou are a biomedical decision-support model for immunotherapy survival risk prediction.\nUse only the supplied sample summary.\nDo not infer outcomes from sample identifiers, row order, or formatting cues.\nRisk score must be on a 0 to 1 scale where higher means higher risk of earlier event and shorter survival.\nThese inputs are sparse genomic alterations, not expression measurements.\nDo not treat alterations in checkpoint genes such as CD274, CTLA4, or PDCD1 as proof of an inflamed tumor microenvironment.\nMajor adverse clues include antigen-presentation escape, STK11 or KEAP1 resistance context, strong cell-cycle or TP53 disruption, MAPK or RTK activation, PI3K signaling, and beta-catenin or immune-exclusion context.\nPotentially favorable context includes high alteration burden, DNA-repair deficiency, POLE or POLD1 or mismatch-repair signals, and PBRM1 or VHL or SETD2-like chromatin context.\nUse the calibration snapshot explicitly as the primary calibration prior.\nIf sparse_genomic_profile is true and there is no clear escape or strong resistance axis, avoid low risk and keep the case intermediate, usually around 0.42 to 0.58.\nLow risk should usually require ultra_favorable_context to be true, repair_supported_favorable to be true, dominant_adverse_axes_count to stay low, and calibrated_net_risk to be clearly negative.\nDo not let very high burden by itself create a low-risk answer.\nIf burden_only_favorable_context is true, default to intermediate unless repair support is also explicit and net risk is clearly negative.\nIf canonical adverse drivers co-occur with strong favorable context, prefer intermediate unless net risk remains clearly positive after calibration.\nIf ultra_favorable_context is true but dominant_adverse_axes_count is 3 or more, prefer intermediate instead of low risk.\nIf calibrated_net_risk falls between about -0.03 and 0.08, prefer intermediate risk instead of forcing a polar answer.\nUse the sign and magnitude of calibrated_net_risk to rank intermediate cases: mildly negative cases can lean lower, mildly positive cases can lean higher.\nIf high_risk_ready is true, strong favorable rescue is absent, and calibrated_net_risk is clearly positive, allow a high-risk prediction with a score typically at or above 0.67.\nMulti-axis adverse context means combinations such as STK11 or KEAP1 plus TP53 or cell-cycle disruption, antigen-presentation escape plus another adverse pathway, or several dominant adverse axes with heavy adverse marker load.\nAvoid collapsing many cases to exactly 0.50 unless the evidence is truly balanced.\nReturn only JSON with risk_group, risk_score, and 3 short rationale items.\n'.strip()}

def resolve_task2_prompt_version(prompt_version: str | None=None) -> str:
    version = str(prompt_version or TASK2_PROMPT_VERSION)
    if version not in TASK2_PROMPT_VERSIONS:
        raise ValueError(f'Unsupported Task 2 prompt version: {version}')
    return version

def build_task2_messages(sample_summary: dict, prompt_version: str | None=None) -> tuple[str, str]:
    version = resolve_task2_prompt_version(prompt_version)
    compact_summary = build_compact_task2_summary(sample_summary, prompt_version=version)
    if version == 'v2.1':
        user_lines = ['Assess this patient for relative survival risk under immunotherapy using the genomic alteration summary only.', 'Higher risk_score means shorter expected survival and earlier event.', 'Altered genes are binary genomic events rather than expression values.', 'Balance adverse resistance-associated signals against potentially favorable immunogenicity-associated context.', 'Use the calibration snapshot as the main tie-breaker for sparse cases and mixed-driver cases.', 'Do not output low risk just because strong adverse drivers are absent in a sparse profile.', 'Allow low risk only when favorable context is explicit and adverse evidence is limited.', 'If high_risk_ready is true and favorable rescue is weak, do not be overly conservative about using high risk.']
    else:
        user_lines = ['Assess this patient for relative survival risk under immunotherapy using the genomic alteration summary only.', 'Higher risk_score means shorter expected survival and earlier event.', 'Altered genes are binary genomic events rather than expression values.', 'Balance adverse resistance-associated signals against potentially favorable immunogenicity-associated context.', 'Use the calibration snapshot as the main tie-breaker for sparse cases and mixed-driver cases.', 'Do not output low risk just because strong adverse drivers are absent in a sparse profile; most such cases should stay intermediate.', 'Allow low risk only when ultra_favorable_context and repair_supported_favorable are explicit and calibrated_net_risk is clearly negative.', 'Do not treat burden_only_favorable_context or isolated chromatin context as enough for low risk.', 'If ultra_favorable_context coexists with 3 or more dominant adverse axes, keep the case intermediate.', 'If calibrated_net_risk is near zero, keep the score intermediate instead of forcing low or high.', 'Use mildly negative net risk to place intermediate cases slightly below 0.50 and mildly positive net risk to place them slightly above 0.50.', 'If high_risk_ready is true and strong favorable rescue is absent, do not be overly conservative about using high risk.']
    user_prompt = '\n'.join([*user_lines, json.dumps(compact_summary, ensure_ascii=False, separators=(',', ':'))])
    return (TASK2_SYSTEM_PROMPTS[version], user_prompt)

def build_compact_task2_summary(sample_summary: dict, prompt_version: str | None=None) -> dict:
    version = resolve_task2_prompt_version(prompt_version)
    top_genes = []
    for gene in sample_summary.get('top_altered_genes', [])[:8]:
        item = {'gene_symbol': gene.get('gene_symbol'), 'dataset_prevalence': gene.get('dataset_prevalence')}
        if gene.get('biological_tags'):
            item['biological_tags'] = gene['biological_tags'][:2]
        top_genes.append(item)
    top_themes = [{'theme': theme.get('theme'), 'matched_gene_count': theme.get('matched_gene_count')} for theme in sample_summary.get('biological_theme_snapshot', [])[:4]]
    top_programs = [{'program': program.get('program'), 'activity_level': program.get('activity_level'), 'relative_activity_score': program.get('relative_activity_score'), 'representative_genes': program.get('representative_genes', [])[:4]} for program in sample_summary.get('program_activity_snapshot', [])[:5]]
    burden_snapshot = sample_summary.get('burden_snapshot', {})
    immunotherapy_snapshot = sample_summary.get('immunotherapy_relevance_snapshot', {})
    compact_summary = {'sample_id': sample_summary.get('sample_id'), 'altered_gene_count': sample_summary.get('altered_gene_count'), 'mutation_burden_proxy': {'altered_gene_count': burden_snapshot.get('altered_gene_count'), 'burden_level': burden_snapshot.get('burden_level'), 'burden_percentile_within_dataset': burden_snapshot.get('burden_percentile_within_dataset')}, 'top_altered_genes': top_genes, 'dominant_biological_themes': top_themes, 'dominant_alteration_programs': top_programs, 'risk_balance': build_risk_balance(sample_summary.get('program_activity_snapshot', []), immunotherapy_snapshot), 'calibration_snapshot': sample_summary.get('calibration_snapshot', {})}
    if version == 'v2.2.1':
        compact_summary['immunotherapy_relevance_snapshot'] = {'adverse_risk_markers': immunotherapy_snapshot.get('adverse_risk_markers', [])[:6], 'favorable_context_markers': immunotherapy_snapshot.get('favorable_context_markers', [])[:6], 'antigen_presentation_escape_hits': immunotherapy_snapshot.get('antigen_presentation_escape_hits', [])[:5], 'dna_repair_instability_hits': immunotherapy_snapshot.get('dna_repair_instability_hits', [])[:5]}
    return compact_summary

def build_risk_balance(programs: list[dict], immunotherapy_snapshot: dict) -> dict:
    adverse = []
    favorable = []
    for program in programs:
        compact = {'program': program.get('program'), 'activity_level': program.get('activity_level'), 'relative_activity_score': program.get('relative_activity_score')}
        program_name = program.get('program')
        if program_name in ADVERSE_PROGRAMS:
            adverse.append(compact)
        elif program_name in FAVORABLE_PROGRAMS:
            favorable.append(compact)
    adverse.sort(key=lambda item: (-float(item['relative_activity_score']), item['program']))
    favorable.sort(key=lambda item: (-float(item['relative_activity_score']), item['program']))
    adverse_strength = float(immunotherapy_snapshot.get('risk_signal_strength', 0.0))
    favorable_strength = float(immunotherapy_snapshot.get('benefit_signal_strength', 0.0))
    return {'adverse_programs': adverse[:3], 'favorable_programs': favorable[:3], 'adverse_strength': round(adverse_strength, 4), 'favorable_strength': round(favorable_strength, 4), 'net_adverse_minus_favorable': round(adverse_strength - favorable_strength, 4)}
